#include "hip_api.h"
using namespace hip_probe;
int main(int argc,char**argv){try{if(argc!=3)throw std::runtime_error("gold MODULE OUTDIR");Api a(7);a.Check(a.hipInit(0),"init");a.Check(a.hipSetDevice(0),"device");Handle m{},s{},pack{},load{};a.Check(a.LoadModule(&m,argv[1]),"module");a.Check(a.hipStreamCreate(&s),"stream");a.Check(a.hipModuleGetFunction(&pack,m,"column_tail_byte_probe"),"pack");a.Check(a.hipModuleGetFunction(&load,m,"column_operand_byte_probe"),"load");unsigned tokens=640;size_t bytes=3*640*1024;void *in{},*col{},*out{};a.Check(a.hipMalloc(&in,bytes),"in");a.Check(a.hipMalloc(&col,bytes),"col");a.Check(a.hipMalloc(&out,3840*32*64),"out");for(unsigned fixture=0;fixture<2;fixture++){std::vector<unsigned char>x(bytes);for(size_t i=0;i<bytes;i++){unsigned b=(i*37+(i/1024)*19+(i/655360)*73)&255;if(fixture&&((b&127)==127))b^=1;x[i]=b;}a.Check(a.hipMemcpy(in,x.data(),bytes,1),"upload");void*pa[]={&in,&col,&tokens};a.Check(a.hipModuleLaunchKernel(pack,3840,1,1,32,1,1,0,s,pa,nullptr),"pack launch");void*la[]={&in,&col,&out,&tokens};a.Check(a.hipModuleLaunchKernel(load,3840,1,1,32,1,1,0,s,la,nullptr),"operand launch");a.Check(a.hipStreamSynchronize(s),"done");std::vector<unsigned char>c(bytes);std::vector<unsigned>w(3840*32*16);a.Check(a.hipMemcpy(c.data(),col,bytes,2),"col read");a.Check(a.hipMemcpy(w.data(),out,w.size()*4,2),"operand read");std::string prefix=std::string(argv[2])+"/fixture"+std::to_string(fixture);std::ofstream(prefix+"-col.bin",std::ios::binary).write((char*)c.data(),bytes);std::ofstream(prefix+"-operands.u32",std::ios::binary).write((char*)w.data(),w.size()*4);size_t cd=0,qd=0,vd=0,ref=0;for(unsigned p=0;p<3;p++)for(unsigned t=0;t<640;t++)for(unsigned ch=0;ch<1024;ch++){size_t addr=p*640*1024+(t/16)*16384+(ch/16)*256+(ch%16)*16+t%16;cd+=c[addr]!=x[(p*640+t)*1024+ch];}for(unsigned bid=0;bid<3840;bid++){unsigned p=bid/1280,local=bid%1280,key=local/32*16,head=local%32;for(unsigned l=0;l<32;l++)for(unsigned j=0;j<2;j++)for(unsigned e=0;e<8;e++){unsigned pos=(bid*32+l)*16+j*8;auto byte=[&](unsigned off){return(w[pos+off+e/4]>>(8*(e%4)))&255;};unsigned eq=x[(p*640+key+l%16)*1024+head*32+j*16+l/16*8+e],ev=x[(p*640+key+l/16*8+e)*1024+head*32+j*16+l%16];ref+=byte(0)!=eq;ref+=byte(4)!=ev;qd+=byte(2)!=eq;vd+=byte(6)!=ev;}}printf("COLUMN_GOLD fixture=%u raw_allbits=%u nonNaN_input=%u producer_inverse_diff=%zu old_reference_diff=%zu QK_TR_diff=%zu V_direct_diff=%zu fullwave=32 tokens=640 planes=3\n",fixture,fixture==0,fixture==1,cd,ref,qd,vd);if(cd||ref||qd||vd)throw std::runtime_error("byte mismatch");}a.hipFree(out);a.hipFree(col);a.hipFree(in);a.hipStreamDestroy(s);a.hipModuleUnload(m);return 0;}catch(const std::exception&e){fprintf(stderr,"GOLD_FAIL %s\n",e.what());return 1;}}
